package dev.bautista.spotlight.data
import dev.bautista.spotlight.automation.Workflows
import dev.bautista.spotlight.personal.PersonalCommands
import dev.bautista.spotlight.search.LocalTools
import org.json.*
/** Only portable preferences. Permissions, access grants, histories and secrets never leave the device. */
object ConfigTransfer {
 private val keys=setOf("focusInterface","focusTypeface","sourcePriority","customThemes","actionOpacity","settingsOpacity","windowScale","uiDensityScale","theme","opacity","width","manualWidth","position","animations","engine","favorites","blur","shortcut","quickLinks","aliases","snippets","pins","accent","appearance","density","messageApp","aiProvider","aiModel","corner","textScale","iconSize","maxHeight","compactSearchResults","adaptive","routines","clipLimit","clipRetention","suggestions","hiddenSuggestions","pinnedSuggestions","preset","clipboardShortcut","keyBindings","autoKeyboard","glassIntensity","surfaceTone","borderWidth","shadowSize","typeface","selectionStyle","movement")
 fun encode(c:Config):String=JSONObject().put("format","spotlight-next").put("version",1).put("settings",JSONObject().apply{
  put("sourcePriority",JSONObject(c.sourcePriority));put("customThemes",ThemeTransfer.portableThemes(c.customThemes));put("autoKeyboard",c.autoKeyboard);put("glassIntensity",c.glassIntensity);put("surfaceTone",c.surfaceTone);put("borderWidth",c.borderWidth);put("shadowSize",c.shadowSize);put("focusInterface",c.focusInterface);put("focusTypeface",c.focusTypeface);put("typeface",c.typeface);put("selectionStyle",c.selectionStyle);put("movement",c.movement);put("keyBindings",JSONArray(c.keyBindings.toList()));put("actionOpacity",c.actionOpacity);put("settingsOpacity",c.settingsOpacity);put("windowScale",c.windowScale);put("uiDensityScale",c.uiDensityScale);put("theme",c.theme);put("opacity",c.opacity);put("width",c.width);put("manualWidth",c.manualWidth);put("position",c.position);put("animations",c.animations);put("engine",c.engine);put("favorites",JSONArray(c.favorites.toList()));put("blur",c.blur);put("shortcut",c.shortcut);put("quickLinks",JSONArray(c.quickLinks.toList()));put("aliases",JSONArray(c.aliases.toList()));put("snippets",JSONArray(c.snippets.toList()));put("pins",JSONArray(c.pins.toList()));put("accent",c.accent);put("appearance",c.appearance);put("density",c.density);put("messageApp",c.messageApp);put("aiProvider",c.aiProvider);put("aiModel",c.aiModel);put("corner",c.corner);put("textScale",c.textScale);put("iconSize",c.iconSize);put("maxHeight",c.maxHeight);put("adaptive",c.adaptive);put("compactSearchResults",c.compactSearchResults);put("routines",JSONArray(c.routines));put("clipLimit",c.clipLimit);put("clipRetention",c.clipRetention);put("suggestions",c.suggestions);put("hiddenSuggestions",JSONArray(c.hiddenSuggestions.toList()));put("pinnedSuggestions",JSONArray(c.pinnedSuggestions.toList()));put("preset",c.preset);put("clipboardShortcut",c.clipboardShortcut)
 }).toString(2)
 fun decode(raw:String,current:Config):Config {
  require(raw.length<=2_000_000){"La configuración supera 2 MB."};val root=JSONObject(raw);require(root.keys().asSequence().toSet()==setOf("format","version","settings") && root.getString("format")=="spotlight-next" && root.getInt("version")==1){"Formato no compatible."};val j=root.getJSONObject("settings");require(j.keys().asSequence().all{it in keys}){"La configuración contiene campos no permitidos."}
  fun str(k:String,old:String,values:Set<String>?=null):String {if(!j.has(k))return old;val v=j.get(k);require(v is String && v.length<=100){"Valor inválido: $k"};if(values!=null)require(v in values){"Opción no compatible: $k"};return v}
  fun number(k:String,old:Float,min:Float,max:Float):Float {if(!j.has(k))return old;val n=j.get(k);require(n is Number);return n.toFloat().also{require(it.isFinite() && it in min..max){"Valor fuera de límites: $k"}}}
  fun integer(k:String,old:Int,min:Int,max:Int):Int {val n=number(k,old.toFloat(),min.toFloat(),max.toFloat());require(n%1f==0f);return n.toInt()}
  fun bool(k:String,old:Boolean)=if(!j.has(k))old else (j.get(k) as? Boolean ?: error("Valor inválido: $k"))
  fun strings(k:String,old:Set<String>,limit:Int=100,length:Int=300):Set<String>{if(!j.has(k))return old;val a=j.getJSONArray(k);require(a.length()<=limit);return (0 until a.length()).map{val s=a.get(it);require(s is String && s.length<=length && !s.contains('\u0000'));s}.toSet()}
  val links=strings("quickLinks",current.quickLinks,50,1000).also{set->require(set.all{LocalTools.validQuickLink(it.substringBefore('|'),it.substringAfter('|',""))}){"Quicklink inválido."}}
  val aliases=strings("aliases",current.aliases,100,1000).also{set->require(set.all{it.contains('|') && PersonalCommands.validAlias(it.substringBefore('|')) && it.substringAfter('|').isNotBlank()})}
  val snippets=strings("snippets",current.snippets,100,8200).also{set->require(set.all{it.contains('|') && PersonalCommands.validAlias(it.substringBefore('|'))})}
  val routines=if(j.has("routines")){val a=j.getJSONArray("routines");require(a.length()<=30);val parsed=Workflows.parse(a.toString());require(parsed.size==a.length() && parsed.map{it.id}.distinct().size==parsed.size){ "Hay rutinas inválidas. No se importó nada." };Workflows.encode(parsed)}else current.routines
  val sourcePriority=if(j.has("sourcePriority"))j.getJSONObject("sourcePriority").also{priorities->
   require(priorities.keys().asSequence().all{it in setOf("Aplicaciones","Archivos","Contactos","Comandos","IA")}){"Fuente desconocida."}
   priorities.keys().asSequence().forEach{key->val n=priorities.get(key);require(n is Number && n.toDouble().isFinite() && n.toDouble()%1.0==0.0 && n.toDouble() in -150.0..150.0){"Prioridad fuera de límites."}}
  }.toString() else current.sourcePriority
  val candidate=current.copy(focusInterface=bool("focusInterface",current.focusInterface),focusTypeface=str("focusTypeface",current.focusTypeface,setOf("geist","inter","system","mono")),sourcePriority=sourcePriority,customThemes=if(j.has("customThemes"))ThemeTransfer.portableThemes(j.getJSONArray("customThemes").toString()).toString() else current.customThemes,autoKeyboard=str("autoKeyboard",current.autoKeyboard,setOf("adaptive","always","never")),glassIntensity=number("glassIntensity",current.glassIntensity,0f,1f),surfaceTone=str("surfaceTone",current.surfaceTone,setOf("neutral","warm","cool")),borderWidth=number("borderWidth",current.borderWidth,0f,2f),shadowSize=number("shadowSize",current.shadowSize,0f,20f),typeface=str("typeface",current.typeface,setOf("inter","system","mono")),selectionStyle=str("selectionStyle",current.selectionStyle,setOf("glass","solid")),movement=str("movement",current.movement,setOf("precise","liquid_precision","liquid_immersive")),keyBindings=strings("keyBindings",current.keyBindings,4,60).also{require(dev.bautista.spotlight.input.KeyboardBindings.validEntries(it)){"Atajos inválidos."}},actionOpacity=number("actionOpacity",current.actionOpacity,.70f,1f),settingsOpacity=number("settingsOpacity",current.settingsOpacity,.70f,1f),windowScale=number("windowScale",current.windowScale,-1f,1f).also{require(it==-1f || it in 0f..1f)},uiDensityScale=number("uiDensityScale",current.uiDensityScale,-1f,1.15f).also{require(it==-1f || it in .85f..1.15f)},theme=str("theme",current.theme,setOf("auto","light","dark")),opacity=number("opacity",current.opacity,.70f,1f),width=if(!j.has("width"))current.width else if(j.get("width") is Number && j.getDouble("width")==0.0)0 else integer("width",current.width,380,1100),manualWidth=integer("manualWidth",current.manualWidth,300,1100),position=number("position",current.position,.04f,.3f),animations=bool("animations",current.animations),engine=str("engine",current.engine,setOf("google","duckduckgo","bing")),favorites=strings("favorites",current.favorites),blur=bool("blur",current.blur),shortcut=str("shortcut",current.shortcut,setOf("ctrl_alt","alt","ctrl")),quickLinks=links,aliases=aliases,snippets=snippets,pins=strings("pins",current.pins,50,240),accent=str("accent",current.accent,setOf("blue","graphite","purple","rose","green","orange")),appearance=str("appearance",current.appearance,setOf("spotlight","raycast")),density=str("density",current.density,setOf("auto","compact","balanced","spacious")),messageApp=str("messageApp",current.messageApp,setOf("whatsapp","whatsapp_business","sms","email")),aiProvider=str("aiProvider",current.aiProvider,setOf("openai","gemini","backend")),aiModel=str("aiModel",current.aiModel).also{require(it.matches(Regex("[A-Za-z0-9._-]{1,100}")))},corner=integer("corner",current.corner,12,32),textScale=number("textScale",current.textScale,.85f,1.3f),iconSize=integer("iconSize",current.iconSize,24,36),maxHeight=integer("maxHeight",current.maxHeight,320,700),adaptive=bool("adaptive",current.adaptive),compactSearchResults=bool("compactSearchResults",current.compactSearchResults),routines=routines,clipLimit=integer("clipLimit",current.clipLimit,5,50),clipRetention=integer("clipRetention",current.clipRetention,1,60),suggestions=bool("suggestions",current.suggestions),hiddenSuggestions=strings("hiddenSuggestions",current.hiddenSuggestions),pinnedSuggestions=strings("pinnedSuggestions",current.pinnedSuggestions),preset=str("preset",current.preset,setOf("glass","pure","hybrid","macos","ios","raycast","graphite")),clipboardShortcut=str("clipboardShortcut",current.clipboardShortcut,setOf("ctrl_shift_v","ctrl_p","off")))
  if(j.has("keyBindings"))candidate.keyBindings.forEach { entry ->
   val id=entry.substringBefore('=');val chord=dev.bautista.spotlight.input.KeyChord.decode(entry.substringAfter('='))!!
   require(dev.bautista.spotlight.input.KeyboardBindings.conflict(candidate,id,chord)==null){"El respaldo contiene atajos en conflicto."}
  }
  return candidate
 }
 fun summary(c:Config)="${JSONArray(c.customThemes).length()} temas · "+"${c.favorites.size} favoritos · ${c.snippets.size} fragmentos · ${Workflows.parse(c.routines).size} rutinas · ${c.quickLinks.size} quicklinks · ${c.aliases.size} alias"
}
